    bEl.classList.add('on'); const cv = $('canvas', bEl); const L2 = new ET.Landscape(cv, 'night'); L2.draw(2);
    let s = 2 * 3600 + 41 * 60 + 9; clearInterval(bTimer); bTimer = setInterval(() => { s--; const e = $('#bLeft'); if (!e) return clearInterval(bTimer); e.textContent = [Math.floor(s / 3600), Math.floor((s % 3600) / 60), s % 60].map((v) => String(v).padStart(2, '0')).join(':'); }, 1000);
