    requestAnimationFrame(() => tEl.classList.add('on')); let s = 18 * 60 + 42, paused = false; clearInterval(tInt); tInt = setInterval(() => { if (paused) return; s = Math.max(0, s - 1); $('#trT').textContent = `${Math.floor(s / 60)}:${String(s % 60).padStart(2, '0')}`; $('#trP').style.width = (1 - s / 1500) * 100 + '%'; }, 1000); $('#trP').style.width = (1 - s / 1500) * 100 + '%';
