    <div class="tstep" data-i="3"><div class="shieldbig" style="width:104px;height:104px;border-radius:34px">${ico('link')}</div><h2>${t.s4[0]}</h2><p>${t.s4[1]}</p><div class="pairbox"><span class="code" style="font-size:30px;padding:16px 22px">${code}</span><button class="btn-s" id="tCopy" type="button">${t.copy}</button></div><div class="tbtns"><button class="ghost-btn" data-prev type="button">${t.back}</button><button class="cta" data-next type="button"><span>${t.next}</span></button></div></div>
